    if (sql[i] === ';' || sql[i] === '\0') throw new TypeError('MSSQL_SINGLE_SELECT_REQUIRED');
    if (sql[i] === '(') depth++;
    if (sql[i] === ')' && --depth < 0) throw new TypeError('MSSQL_UNBALANCED_QUERY');
