  for(const [key,max]of Object.entries(COMPARISON_LIMITS))
    need(Number.isSafeInteger(selected[key])&&selected[key]>=1&&selected[key]<=max,'LIMIT','Choose a valid '+key+'.');
  return selected;
}
function sourceIdentity(collection) {
