    need(OUTPUT.test(path)&&!path.startsWith('analysis/')&&!['selection.json','collection.json'].includes(path)&&
      plain(file)&&Number.isSafeInteger(file.bytes)&&file.bytes>=0&&file.bytes<=MAX_DOCUMENT_BYTES&&HASH.test(file.sha256),
